 +	}
 +	if runtime.GOOS != "windows" {
 +		info, err := os.Stat(target)
 +		if err != nil {
 +			t.Fatal(err)
 +		}
 +		if got := info.Mode().Perm(); got != 0o600 {
 +			t.Fatalf("permission = %#o, want %#o", got, 0o600)
 +		}
 +	}
 +	assertNoAtomicTemps(t, dir)
 +}
