 +
 +type faultSyncCloser struct {
 +	syncErr     error
 +	closeErr    error
 +	syncCalled  bool
 +	closeCalled bool
 +}
 +
 +func (f *faultSyncCloser) Sync() error {
 +	f.syncCalled = true
 +	return f.syncErr
 +}
 +
 +func (f *faultSyncCloser) Close() error {
 +	f.closeCalled = true
 +	return f.closeErr
 +}
 +
 +func (f *faultWriteFile) Sync() error {
 +	if f.syncErr != nil {
