 +type faultWriteFile struct {
 +	*os.File
 +
 +	syncErr  error
 +	closeErr error
 +}
 +
 +type faultReadFile struct {
 +	*os.File
 +
 +	closeErr error
 +}
 +
 +type faultReadCloser struct {
 +	readErr error
 +	closed  bool
 +}
 +
 +type faultSyncCloser struct {
 +	syncErr     error
 +	closeErr    error
 +	syncCalled  bool
 +	closeCalled bool
 +}
 +
 +func (f *faultSyncCloser) Sync() error {
 +	f.syncCalled = true
 +	return f.syncErr
 +}
 +
 +func (f *faultSyncCloser) Close() error {
 +	f.closeCalled = true
 +	return f.closeErr
 +}
 +
 +func (f *faultWriteFile) Sync() error {
 +	if f.syncErr != nil {
 +		return f.syncErr
 +	}
 +	return f.File.Sync()
 +}
 +
 +func (f *faultWriteFile) Close() error {
 +	err := f.File.Close()
 +	if f.closeErr != nil {
 +		return f.closeErr
 +	}
 +	return err
 +}
 +
 +func (f *faultReadFile) Close() error {
 +	err := f.File.Close()
 +	if f.closeErr != nil {
 +		return f.closeErr
 +	}
 +	return err
 +}
 +
 +func (f *faultReadCloser) Read([]byte) (int, error) { return 0, f.readErr }
 +
 +func (f *faultReadCloser) Close() error {
 +	f.closed = true
 +	return nil
 +}
